var https = require('https');

// ── Config ────────────────────────────────────────────────────────────────
var SUPABASE_URL = 'https://pddktbfaaltxvlxcfoaq.supabase.co';
var SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBkZGt0YmZhYWx0eHZseGNmb2FxIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NjAxMTE4NywiZXhwIjoyMDkxNTg3MTg3fQ.RENRUw7InVDoluXG8oL7oyPylzFvInDuqiQxvIVuvHo';
var GRAPH       = 'https://graph.facebook.com/v21.0';
var sbHeaders   = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

// ── Resolver URL do Google Drive (imagem) ────────────────────────────────
function resolveUrl(url) {
  if (!url) return null;
  var match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return 'https://lh3.googleusercontent.com/d/' + match[1];
  return url;
}

// ── Resolver URL do Google Drive (vídeo — download direto) ───────────────
function resolveVideoUrl(url) {
  if (!url) return null;
  var match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return 'https://drive.usercontent.google.com/download?id=' + match[1] + '&export=download&confirm=t';
  return url;
}

// ── Detectar se URL é de vídeo (por extensão) ────────────────────────────
function isVideoUrl(url) {
  if (!url) return false;
  return /\.(mp4|mov|avi|webm|m4v)/i.test(url);
}

// ── Detectar se é URL do Google Drive (sem extensão visível) ──────────────
function isDriveUrl(url) {
  if (!url) return false;
  return /drive\.google\.com/.test(url);
}

// ── Helpers HTTP ──────────────────────────────────────────────────────────
function parseJson(str) {
  try { return JSON.parse(str); } catch(e) { return {}; }
}

function parseHost(urlStr) {
  var s = urlStr.replace('https://', '');
  var idx = s.indexOf('/');
  return { host: idx === -1 ? s : s.substring(0, idx),
           path: idx === -1 ? '/' : s.substring(idx) };
}

function httpsGet(urlStr, headers) {
  return new Promise(function(resolve, reject) {
    var u = parseHost(urlStr);
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'GET', headers: headers || {} },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(parseJson(data)); });
      }
    );
    req.on('error', reject);
    req.end();
  });
}

function httpsPatch(urlStr, body, headers) {
  return new Promise(function(resolve, reject) {
    var bodyStr = JSON.stringify(body);
    var u = parseHost(urlStr);
    var allHeaders = Object.assign(
      { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      headers || {}
    );
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'PATCH', headers: allHeaders },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(data); });
      }
    );
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

function toFormBody(obj) {
  var parts = [];
  var keys = Object.keys(obj);
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i]; var v = obj[k];
    if (v !== undefined && v !== null) {
      parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v)));
    }
  }
  return parts.join('&');
}

function postForm(urlStr, params) {
  return new Promise(function(resolve, reject) {
    var body = toFormBody(params);
    var u = parseHost(urlStr);
    var req = https.request(
      { hostname: u.host, path: u.path, method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
      function(res) {
        var data = '';
        res.on('data', function(c) { data += c; });
        res.on('end',  function()  { resolve(parseJson(data)); });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function igCreateAndPublish(igId, containerParams, pageToken) {
  var containerResp = await postForm(GRAPH + '/' + igId + '/media', containerParams);
  if (containerResp.error) return { post_id: null, error: containerResp.error.message };
  if (!containerResp.id)   return { post_id: null, error: 'Instagram nao retornou creation_id' };

  // Aguardar container ficar FINISHED (Instagram precisa processar a mídia)
  var maxTentativas = 20;
  for (var t = 0; t < maxTentativas; t++) {
    var statusResp = await httpsGet(
      GRAPH + '/' + containerResp.id + '?fields=status_code&access_token=' + pageToken,
      {}
    );
    if (statusResp.status_code === 'FINISHED') break;
    if (statusResp.status_code === 'ERROR') {
      return { post_id: null, error: 'Instagram: erro ao processar midia - ' + JSON.stringify(statusResp) };
    }
    // Aguarda 2 segundos antes de tentar novamente
    await new Promise(function(r) { setTimeout(r, 2000); });
  }

  var publishResp = await postForm(GRAPH + '/' + igId + '/media_publish', {
    creation_id: containerResp.id, access_token: pageToken,
  });
  return {
    post_id: publishResp.id || null,
    error: publishResp.error ? publishResp.error.message : null,
  };
}

// ── Horário Brasília (UTC-3) ───────────────────────────────────────────────
var utcNow = new Date();
var brasilia = new Date(utcNow.getTime() - 3 * 60 * 60 * 1000);
var year  = brasilia.getFullYear();
var month = String(brasilia.getMonth() + 1).padStart(2, '0');
var day   = String(brasilia.getDate()).padStart(2, '0');
var hours = String(brasilia.getHours()).padStart(2, '0');
var mins  = String(brasilia.getMinutes()).padStart(2, '0');
var today       = year + '-' + month + '-' + day;
var currentTime = hours + ':' + mins;

// ── Buscar conteúdos com status 'publishing' (Publicar Agora imediato) ──────
var immediateUrl = SUPABASE_URL + '/rest/v1/contents' +
  '?select=id,client_id,type,caption,generated_image_url,media_urls,scheduled_date,scheduled_time' +
  '&status=eq.publishing';

var immediateContents = await httpsGet(immediateUrl, sbHeaders);
if (!Array.isArray(immediateContents)) immediateContents = [];

// ── Buscar conteúdos aprovados com data <= hoje ───────────────────────────
var contentsUrl = SUPABASE_URL + '/rest/v1/contents' +
  '?select=id,client_id,type,caption,generated_image_url,media_urls,scheduled_date,scheduled_time' +
  '&status=eq.approved_by_client' +
  '&scheduled_date=lte.' + today;

var contents = await httpsGet(contentsUrl, sbHeaders);
if (!Array.isArray(contents)) contents = [];

// ── Filtrar agendados prontos (hora chegou) ────────────────────────────────
var scheduledReady = [];
for (var i = 0; i < contents.length; i++) {
  var c = contents[i];
  var cTime = c.scheduled_time || '09:00';
  if (c.scheduled_date < today || (c.scheduled_date === today && cTime <= currentTime)) {
    scheduledReady.push(c);
  }
}

// Imediatos primeiro, depois agendados
var ready = immediateContents.concat(scheduledReady);

if (ready.length === 0) {
  return [{ json: { published: 0, message: 'Nenhum conteudo para publicar agora (' + today + ' ' + currentTime + ')' } }];
}

// ── Publicar cada conteúdo ────────────────────────────────────────────────
var results = [];

for (var j = 0; j < ready.length; j++) {
  var content = ready[j];
  var result  = { content_id: content.id, facebook: null, instagram: null, error: null };

  try {
    var clientsResp = await httpsGet(
      SUPABASE_URL + '/rest/v1/clients?select=facebook_page_id,facebook_page_token,instagram_account_id&id=eq.' + content.client_id,
      sbHeaders
    );
    var client = Array.isArray(clientsResp) && clientsResp.length > 0 ? clientsResp[0] : null;

    if (!client || !client.facebook_page_id || !client.facebook_page_token) {
      result.error = 'Cliente sem integracoes Meta configuradas';
      results.push(result);
      continue;
    }

    // System User Token (não expira, não precisa de aprovação do app Meta)
    var SYSTEM_USER_TOKEN = 'EAAU7TJPfNhABRWZBZBoG8ZBcvD0Mh46CeyOjfSEXk9vMxqSZANTZB78FtzxbDgT6QjjjFFRnJFsrsKBE9oQwl53emkTELkbclUrFgKKYT8ZANEDluKhCc83Wk68QUrpYJi12jUqtZBp8DhfIsUbKY7X2n0SQJ3BLoZAojN4oP3KLy5owgRBuwMBUkcxrTzqclAZDZD';
    var pageToken = SYSTEM_USER_TOKEN;

    var type    = content.type || 'imagem';
    var isStory = type === 'story';
    var resolvedImageUrl = resolveUrl(content.generated_image_url);

    // ── Facebook ──────────────────────────────────────────────────────────
    var fbPostId = null, fbError = null;
    try {
      var fbParams = {}, fbResp = {};

      if (isStory) {
        // Story: publica cada frame como story separado (imagem ou vídeo)
        var storyUrlsFb = (content.media_urls && content.media_urls.length > 0)
          ? content.media_urls : (resolvedImageUrl ? [resolvedImageUrl] : []);
        for (var sf = 0; sf < storyUrlsFb.length; sf++) {
          // Drive URLs sem extensão são tratadas como vídeo (a maioria dos stories é vídeo)
          var isVidFb    = isVideoUrl(storyUrlsFb[sf]) || isDriveUrl(storyUrlsFb[sf]);
          var frameUrlFb = isVidFb ? resolveVideoUrl(storyUrlsFb[sf]) : resolveUrl(storyUrlsFb[sf]);
          var fbStoryParams = { access_token: pageToken };
          if (isVidFb) { fbStoryParams.file_url = frameUrlFb; } else { fbStoryParams.url = frameUrlFb; }
          fbResp = await postForm(
            GRAPH + '/' + client.facebook_page_id + (isVidFb ? '/video_stories' : '/photo_stories'),
            fbStoryParams
          );
          if (fbResp.post_id || fbResp.id) fbPostId = fbResp.post_id || fbResp.id;
          if (fbResp.error && !fbPostId) fbError = fbResp.error.message;
        }

      } else if (type === 'reel') {
        // Reel: usa endpoint de vídeo com URL de download direto (Drive)
        fbParams = {
          file_url:     resolveVideoUrl(content.generated_image_url),
          published:    'true',
          access_token: pageToken,
        };
        if (content.caption) fbParams.description = content.caption;
        fbResp   = await postForm(GRAPH + '/' + client.facebook_page_id + '/videos', fbParams);
        fbPostId = fbResp.id || null;
        fbError  = fbResp.error ? fbResp.error.message : null;

      } else if (type === 'carrossel' && content.media_urls && content.media_urls.length >= 2) {
        // Carrossel Facebook: multi-photo post com attached_media
        var photoIds = [];
        for (var cp = 0; cp < content.media_urls.length; cp++) {
          var photoResp = await postForm(GRAPH + '/' + client.facebook_page_id + '/photos', {
            url:          resolveUrl(content.media_urls[cp]),
            published:    'false',
            access_token: pageToken,
          });
          if (photoResp.id) photoIds.push({ media_fbid: photoResp.id });
        }
        if (photoIds.length >= 1) {
          fbResp = await postForm(GRAPH + '/' + client.facebook_page_id + '/feed', {
            message:        content.caption || '',
            attached_media: JSON.stringify(photoIds),
            published:      'true',
            access_token:   pageToken,
          });
          fbPostId = fbResp.id || null;
          fbError  = fbResp.error ? fbResp.error.message : null;
        }

      } else {
        // Imagem simples
        var imgUrl = resolvedImageUrl;
        var fbEndpoint = imgUrl
          ? GRAPH + '/' + client.facebook_page_id + '/photos'
          : GRAPH + '/' + client.facebook_page_id + '/feed';
        fbParams = { published: 'true', access_token: pageToken };
        if (imgUrl) { fbParams.url = imgUrl; fbParams.caption = content.caption || ''; }
        else        { fbParams.message = content.caption || ''; }
        fbResp   = await postForm(fbEndpoint, fbParams);
        fbPostId = fbResp.id || null;
        fbError  = fbResp.error ? fbResp.error.message : null;
      }
    } catch(e) { fbError = String(e.message); }

    result.facebook = { post_id: fbPostId, error: fbError };

    // ── Instagram ─────────────────────────────────────────────────────────
    var igPostId = null, igError = null;

    if (client.instagram_account_id) {
      try {
        var igResult = {};

        if (type === 'carrossel' && content.media_urls && content.media_urls.length >= 2) {
          // Carrossel Instagram
          var itemIds = [];
          for (var k = 0; k < content.media_urls.length; k++) {
            var itemResp = await postForm(GRAPH + '/' + client.instagram_account_id + '/media', {
              image_url:        resolveUrl(content.media_urls[k]),
              is_carousel_item: 'true',
              access_token:     pageToken,
            });
            if (itemResp.error) { igError = itemResp.error.message; break; }
            if (itemResp.id)    itemIds.push(itemResp.id);
          }
          if (!igError && itemIds.length >= 2) {
            igResult = await igCreateAndPublish(client.instagram_account_id, {
              media_type:   'CAROUSEL',
              children:     itemIds.join(','),
              caption:      content.caption || '',
              access_token: pageToken,
            }, pageToken);
            igPostId = igResult.post_id; igError = igResult.error;
          }

        } else if (type === 'reel') {
          // Reel Instagram: usa URL de download direto (Drive)
          igResult = await igCreateAndPublish(client.instagram_account_id, {
            media_type:   'REELS',
            video_url:    resolveVideoUrl(content.generated_image_url),
            caption:      content.caption || '',
            access_token: pageToken,
          }, pageToken);
          igPostId = igResult.post_id; igError = igResult.error;

        } else if (isStory) {
          // Story Instagram: publica cada frame como story separado
          var storyUrlsIg = (content.media_urls && content.media_urls.length > 0)
            ? content.media_urls : (resolvedImageUrl ? [resolvedImageUrl] : []);
          for (var si = 0; si < storyUrlsIg.length; si++) {
            // Drive URLs sem extensão são tratadas como vídeo
            var isVidIg    = isVideoUrl(storyUrlsIg[si]) || isDriveUrl(storyUrlsIg[si]);
            var frameUrlIg = isVidIg ? resolveVideoUrl(storyUrlsIg[si]) : resolveUrl(storyUrlsIg[si]);
            var igStoryParams = { media_type: 'STORIES', access_token: pageToken };
            if (isVidIg) { igStoryParams.video_url = frameUrlIg; } else { igStoryParams.image_url = frameUrlIg; }
            igResult = await igCreateAndPublish(client.instagram_account_id, igStoryParams, pageToken);
            if (igResult.post_id) igPostId = igResult.post_id;
            if (igResult.error && !igPostId) igError = igResult.error;
          }

        } else if (resolvedImageUrl) {
          // Imagem simples Instagram
          igResult = await igCreateAndPublish(client.instagram_account_id, {
            image_url:    resolvedImageUrl,
            caption:      content.caption || '',
            access_token: pageToken,
          }, pageToken);
          igPostId = igResult.post_id; igError = igResult.error;
        }
      } catch(e) { igError = String(e.message); }
    }

    result.instagram = { post_id: igPostId, error: igError };

    // ── Atualizar Supabase ─────────────────────────────────────────────────
    if (fbPostId || igPostId) {
      var updateData = { status: 'published' };
      if (fbPostId) updateData.facebook_post_id  = fbPostId;
      if (igPostId) updateData.instagram_post_id = igPostId;
      await httpsPatch(
        SUPABASE_URL + '/rest/v1/contents?id=eq.' + content.id,
        updateData,
        sbHeaders
      );
    }

  } catch(e) {
    result.error = String(e.message);
  }

  results.push(result);
}

return [{ json: { published: results.length, brasilia_time: today + ' ' + currentTime, results: results } }];
